import { loadFont } from "@remotion/google-fonts/Baloo2";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// BRINQ BABY SCHOOL (cliente da agência Digitall Max / Renato). Matrículas 2027, duas copies do cliente = dois vídeos.
// Jeito: vitrine. As fotos da escola ocupam o quadro inteiro, com aproximação lenta e deslize curto, e trocam no ritmo da fala;
// o texto é um lettering em bloco azul do logo na parte de baixo (linha branca + destaque amarelo). Por cima, motions leves:
// selo dos 30 anos, balão "Hello! Olá!", pino do endereço. Fecha com o logo e o "Saiba mais".
// Identidade: azul #3048D8, amarelo #FFD000, roxo #9A6CF6, rosa #F27ED9, ciano #2FD3F5 (tirados do logo); Baloo 2.
// Tempos = tempos da voz cortada de cada copy (t = 0 é o começo do wav; o vídeo tem LEAD de entrada).

const { fontFamily: F } = loadFont("normal", { weights: ["600", "700", "800"], subsets: ["latin", "latin-ext"] });

export const BQ_FPS = 30;
const LEAD = 0.2;

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.6));
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);

const BLUE = "#3048D8";
const BLUE_D = "#1F2F9E";
const YEL = "#FFD000";
const PURP = "#9A6CF6";
const PINK = "#F27ED9";
const CYAN = "#2FD3F5";
const WH = "#FFFFFF";

// ───────── fotos ─────────
// cam: z = aproximação (+ entra, − afasta), x/y = deslize em px ao longo da foto
type Shot = { at: number; src: string; z: number; x?: number; y?: number; pan?: boolean; tr: "fade" | "wipe" | "zoom" | "slide" | "cut" };
const Photo: React.FC<{ s: Shot; t: number; end: number }> = ({ s, t, end }) => {
  const p = lin(t, s.at, end);
  const scale = s.z >= 0 ? 1.06 + s.z * p : 1.06 - s.z * (1 - p);
  if (s.pan) {
    // foto deitada: ocupa a altura toda e desliza de lado
    const w = 1920 * (1524 / 1032);
    const x = -(w - 1080) * (0.08 + 0.84 * p);
    return <Img src={staticFile(s.src)} style={{ position: "absolute", height: 1920 * 1.02, top: -19, left: x, width: w * 1.02, objectFit: "cover" }} />;
  }
  return (
    <Img src={staticFile(s.src)} style={{ position: "absolute", inset: 0, width: 1080, height: 1920, objectFit: "cover", transform: `translate(${((s.x ?? 0) * (p - 0.5)).toFixed(1)}px, ${((s.y ?? 0) * (p - 0.5)).toFixed(1)}px) scale(${scale.toFixed(4)})` }} />
  );
};
const enter = (s: Shot, t: number): React.CSSProperties => {
  const e = k(t, s.at, 0.5);
  if (e >= 1 || s.tr === "cut") return {};
  if (s.tr === "fade") return { opacity: e };
  if (s.tr === "wipe") return { clipPath: `inset(0 ${((1 - e) * 100).toFixed(2)}% 0 0 round 0)` };
  if (s.tr === "zoom") return { opacity: Math.min(1, e * 1.6), transform: `scale(${(1.18 - 0.18 * e).toFixed(4)})` };
  return { transform: `translateY(${((1 - e) * 1920).toFixed(1)}px)` };
};
const Photos: React.FC<{ shots: Shot[]; t: number; until: number }> = ({ shots, t, until }) => (
  <>
    {shots.map((s, i) => {
      const next = i + 1 < shots.length ? shots[i + 1].at : until;
      if (t < s.at || t > next + 0.6) return null;
      return (
        <AbsoluteFill key={i} style={{ overflow: "hidden", ...enter(s, t) }}>
          <Photo s={s} t={t} end={next + 0.6} />
        </AbsoluteFill>
      );
    })}
    {/* degradê leve embaixo para o lettering */}
    <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(10,20,80,0) 55%, rgba(10,20,80,0.45) 100%)" }} />
  </>
);

// ───────── lettering: bloco azul embaixo; cada frase no mesmo lugar, a anterior some antes de a próxima entrar ─────────
type Ph = { a: string; at: number; b?: string; bt?: number; out: number; bs?: number };
const COL = 840;
const fitA = (w: string) => Math.min(92, Math.floor((COL - 88) / (w.length * 0.47)));
const fitB = (w: string, s?: number) => s ?? Math.min(132, Math.floor((COL - 80) / (w.length * 0.56)));
const Lettering: React.FC<{ t: number; ph: Ph[] }> = ({ t, ph }) => (
  <>
    {ph.map((p, i) => {
      if (t < p.at - 0.05 || t > p.out + 0.2) return null;
      const e = pop(t, p.at, 0.42);
      const o = lin(t, p.out, p.out + 0.16);
      const eb = p.bt === undefined ? 0 : pop(t, p.bt, 0.4);
      return (
        <div key={i} style={{ position: "absolute", left: 120, right: 120, top: 1300, display: "flex", flexDirection: "column", alignItems: "center", opacity: (1 - o) * Math.min(1, e * 2), transform: `translateY(${((1 - e) * 60).toFixed(1)}px)` }}>
          {p.a ? <div style={{ background: BLUE, color: WH, fontFamily: F, fontWeight: 800, fontSize: fitA(p.a), lineHeight: 1.05, padding: "20px 44px 14px", borderRadius: 34, whiteSpace: "nowrap", boxShadow: "0 18px 40px rgba(16,24,90,0.35)" }}>{p.a}</div> : null}
          {p.b ? (
            <div style={{ marginTop: p.a ? -10 : 0, background: YEL, color: BLUE_D, fontFamily: F, fontWeight: 800, fontSize: fitB(p.b, p.bs), lineHeight: 1.0, padding: "18px 40px 8px", borderRadius: 30, whiteSpace: "nowrap", textTransform: "uppercase", letterSpacing: "-0.01em", boxShadow: "0 18px 40px rgba(16,24,90,0.3)", opacity: Math.min(1, eb * 2), transform: `scale(${(0.7 + 0.3 * eb).toFixed(4)}) rotate(${((1 - eb) * -4 - 1.5).toFixed(2)}deg)` }}>{p.b}</div>
          ) : null}
        </div>
      );
    })}
  </>
);

// ───────── motions leves por cima ─────────
const LogoBadge: React.FC<{ t: number; at: number; out: number }> = ({ t, at, out }) => {
  const e = pop(t, at, 0.5);
  const o = lin(t, out, out + 0.25);
  return (
    <div style={{ position: "absolute", left: 540 - 105, top: 110, width: 210, height: 210, borderRadius: 210, background: WH, boxShadow: "0 16px 40px rgba(0,0,0,0.22)", display: "flex", alignItems: "center", justifyContent: "center", opacity: Math.min(1, e * 2) * (1 - o), transform: `scale(${(e * (1 - 0.3 * o)).toFixed(4)})` }}>
      <Img src={staticFile("brinq/logo.png")} style={{ width: 196 }} />
    </div>
  );
};
const Seal30: React.FC<{ t: number; at: number; out: number }> = ({ t, at, out }) => {
  const e = pop(t, at, 0.55);
  const o = lin(t, out, out + 0.2);
  return (
    <div style={{ position: "absolute", left: 540 - 170, top: 420, width: 340, height: 340, borderRadius: 340, background: YEL, border: `14px solid ${WH}`, boxSizing: "border-box", boxShadow: "0 22px 50px rgba(0,0,0,0.3)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", fontFamily: F, opacity: Math.min(1, e * 2) * (1 - o), transform: `scale(${(e * (1 + 0.02 * Math.sin(t * 3))).toFixed(4)}) rotate(${((1 - e) * -30 - 6).toFixed(2)}deg)` }}>
      <div style={{ fontWeight: 800, fontSize: 150, color: BLUE, lineHeight: 0.9, marginTop: 20 }}>30</div>
      <div style={{ fontWeight: 800, fontSize: 52, color: BLUE_D, lineHeight: 1, marginTop: 4 }}>anos</div>
    </div>
  );
};
const Bubble: React.FC<{ t: number; at: number; out: number }> = ({ t, at, out }) => {
  const e1 = pop(t, at, 0.45), e2 = pop(t, at + 0.3, 0.45);
  const o = lin(t, out, out + 0.2);
  const b = (txt: string, bg: string, e: number, x: number, y: number, tail: "l" | "r") => (
    <div style={{ position: "absolute", left: x, top: y, background: bg, color: WH, fontFamily: F, fontWeight: 800, fontSize: 84, padding: "22px 52px 12px", borderRadius: 60, borderBottomLeftRadius: tail === "l" ? 10 : 60, borderBottomRightRadius: tail === "r" ? 10 : 60, boxShadow: "0 18px 40px rgba(0,0,0,0.25)", opacity: Math.min(1, e * 2) * (1 - o), transform: `scale(${e.toFixed(4)}) translateY(${(Math.sin(t * 2.4 + x) * 6).toFixed(1)}px)`, transformOrigin: tail === "l" ? "0% 100%" : "100% 100%" }}>{txt}</div>
  );
  return (
    <>
      {b("Hello!", PURP, e1, 150, 360, "l")}
      {b("Olá!", PINK, e2, 590, 560, "r")}
    </>
  );
};
const Pin: React.FC<{ t: number; at: number; out: number }> = ({ t, at, out }) => {
  const e = pop(t, at, 0.5);
  const o = lin(t, out, out + 0.2);
  return (
    <div style={{ position: "absolute", left: 540 - 95, top: 520, opacity: Math.min(1, e * 2) * (1 - o), transform: `translateY(${((1 - e) * -200 + Math.sin(t * 3) * 10).toFixed(1)}px)`, filter: "drop-shadow(0 18px 26px rgba(0,0,0,0.35))" }}>
      <svg width={190} height={190} viewBox="0 0 24 24"><path d="M12 22s7-6.6 7-12.2A7 7 0 0 0 5 9.8C5 15.4 12 22 12 22z" fill={PINK} stroke={WH} strokeWidth={1.2} /><circle cx="12" cy="9.6" r="2.8" fill={WH} /></svg>
    </div>
  );
};

// ───────── fecho: logo + Saiba mais ─────────
const Final: React.FC<{ t: number; at: number; cta2: string; cta2At: number }> = ({ t, at, cta2, cta2At }) => {
  const bg = k(t, at - 0.15, 0.55);
  const m = pop(t, at + 0.1, 0.6);
  const btn = pop(t, at + 0.55, 0.5);
  const tap = Math.max(0, Math.sin(lin(t, at + 1.4, at + 1.8) * Math.PI));
  const c2 = pop(t, cta2At, 0.45);
  const blocks: [string, number, number, number][] = [[CYAN, 120, 220, -12], [PINK, 860, 300, 10], [PURP, 150, 1580, 8], [YEL, 850, 1640, -9]];
  return (
    <AbsoluteFill style={{ background: WH, clipPath: `circle(${(bg * 120).toFixed(1)}% at 50% 50%)` }}>
      {/* cubinhos do logo nos cantos, flutuando */}
      {blocks.map(([c, x, y, r], i) => {
        const e = pop(t, at + 0.2 + i * 0.1, 0.5);
        return <div key={i} style={{ position: "absolute", left: x - 50, top: y - 50, width: 100, height: 100, borderRadius: 26, background: c, opacity: 0.9, transform: `scale(${e.toFixed(3)}) rotate(${(r + Math.sin(t * 2 + i) * 8).toFixed(1)}deg) translateY(${(Math.sin(t * 2.2 + i * 1.3) * 12).toFixed(1)}px)` }} />;
      })}
      <div style={{ position: "absolute", left: 0, right: 0, top: 280, display: "flex", justifyContent: "center", opacity: Math.min(1, m * 2), transform: `scale(${(0.5 + 0.5 * m + 0.012 * Math.sin(t * 2.4)).toFixed(4)})` }}>
        <Img src={staticFile("brinq/logo.png")} style={{ width: 780 }} />
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, top: 1170, display: "flex", justifyContent: "center", opacity: Math.min(1, btn * 2) }}>
        <div style={{ position: "relative", background: BLUE, color: WH, fontFamily: F, fontWeight: 800, fontSize: 80, padding: "34px 74px 22px", borderRadius: 100, whiteSpace: "nowrap", boxShadow: "0 18px 40px rgba(16,24,90,0.3)", transform: `scale(${(btn * (1 - 0.06 * tap)).toFixed(4)})` }}>
          Clique em <span style={{ color: YEL }}>“Saiba mais”</span>
          {t > at + 1.4 && t < at + 2.2 ? <div style={{ position: "absolute", inset: -lin(t, at + 1.4, at + 2.2) * 60, borderRadius: 200, border: `6px solid ${BLUE}`, opacity: 1 - lin(t, at + 1.4, at + 2.2) }} /> : null}
        </div>
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, top: 1380, display: "flex", justifyContent: "center", fontFamily: F, fontWeight: 800, fontSize: 80, color: BLUE_D, opacity: Math.min(1, c2 * 2), transform: `scale(${(0.8 + 0.2 * c2).toFixed(4)})` }}>{cta2}</div>
    </AbsoluteFill>
  );
};

// ───────── as duas versões ─────────
type Cfg = { dur: number; shots: Shot[]; ph: Ph[]; logo: [number, number]; seal: [number, number]; bubble: [number, number]; pin: [number, number]; final: number; cta2: string; cta2At: number };

const COPY1: Cfg = {
  dur: 24.6,
  // abre na fachada de verdade, afastando devagar
  shots: [
    { at: -1, src: "brinq/f06.jpg", z: -0.16, tr: "cut" },
    { at: 2.7, src: "brinq/f12.jpg", z: 0.1, y: -40, tr: "zoom" },
    { at: 4.6, src: "brinq/f01.jpg", z: 0.08, x: 60, tr: "wipe" },
    { at: 7.05, src: "brinq/f09.jpg", z: -0.1, tr: "fade" },
