// copy 1: 0,8 s de silêncio tirado da voz depois de "acolhedor" (11,3 s); os tempos acima são os de antes do corte
const CUT1 = (x: number) => (x > 11.3 ? x - 0.8 : x);
const shift = (c: Cfg, f: (x: number) => number): Cfg => ({
  ...c, dur: f(c.dur), final: f(c.final), cta2At: f(c.cta2At),
  shots: c.shots.map((s) => ({ ...s, at: f(s.at) })),
  ph: c.ph.map((p) => ({ ...p, at: f(p.at), bt: p.bt === undefined ? undefined : f(p.bt), out: f(p.out) })),
  logo: [f(c.logo[0]), f(c.logo[1])], seal: [f(c.seal[0]), f(c.seal[1])], bubble: [f(c.bubble[0]), f(c.bubble[1])], pin: [f(c.pin[0]), f(c.pin[1])],
});
const COPY1C = shift(COPY1, CUT1);
export const BQ1_FRAMES = Math.round(COPY1C.dur * BQ_FPS);
