// v2 (ajuste 17/10): voz regravada no eleven_multilingual_v2 ("na Brinq", "bilíngue" sem o u). Os tempos acima continuam
// os da voz v1; esta tabela, palavra por palavra, converte tempo antigo → tempo da voz nova (edit/tabela-copyN-v3b.json).
type Tab = [number, number][];
const TAB1: Tab = [[0.15, 0.09], [0.77, 0.65], [1.35, 1.13], [1.91, 1.33], [2.76, 2.39], [2.94, 2.55], [3.44, 2.83], [3.84, 3.13], [4.72, 3.97], [5.02, 4.29], [5.4, 4.71], [5.76, 5.05], [6.2, 5.37], [6.32, 5.51], [7.16, 6.15], [7.3, 6.31], [7.36, 6.41], [7.74, 6.81], [8.3, 7.31], [8.4, 7.41], [9.19, 8.19], [9.29, 8.27], [9.39, 8.37], [9.97, 8.89], [10.51, 9.29], [10.59, 9.39], [12.53, 10.38], [12.95, 10.72], [13.09, 10.84], [14.03, 11.46], [14.26, 11.72], [14.7, 12.06], [15.08, 12.36], [15.16, 12.44], [15.68, 13.46], [17.54, 14.21], [17.86, 14.45], [18.97, 15.61], [19.29, 15.89], [19.49, 16.07], [19.79, 16.41], [20.32, 16.81], [20.44, 16.93], [20.84, 17.31], [20.96, 17.45], [21.4, 17.93], [21.6, 18.13], [22.2, 18.55], [22.48, 18.77]];
const TAB2: Tab = [[0.09, 0.09], [0.73, 0.67], [1.27, 1.13], [1.87, 1.33], [2.81, 2.88], [3.17, 3.22], [3.27, 3.32], [3.52, 3.58], [3.63, 3.72], [3.88, 3.92], [4.16, 4.14], [4.28, 4.26], [4.6, 4.62], [5.18, 5.14], [5.3, 5.24], [5.66, 5.68], [5.98, 5.9], [6.48, 6.18], [6.6, 6.26], [7.2, 6.8], [7.3, 6.92], [8.3, 7.77], [8.9, 8.24], [9.42, 8.69], [9.5, 8.77], [10.51, 9.73], [10.71, 10.33], [11.1, 10.65], [12.43, 10.93], [12.63, 10.99], [13.05, 12.25], [13.79, 13.31], [14.07, 13.55], [15.07, 14.29], [15.94, 15.11], [16.28, 15.51], [16.5, 15.63], [16.78, 15.93], [17.44, 16.41], [17.54, 16.53], [18.04, 16.95], [18.22, 17.11]];
const viaTab = (tab: Tab) => (x: number) => {
  if (x <= tab[0][0]) return x + tab[0][1] - tab[0][0];
  for (let i = 1; i < tab.length; i++) {
    const [a0, b0] = tab[i - 1], [a1, b1] = tab[i];
    if (x <= a1) return b0 + ((x - a0) / (a1 - a0)) * (b1 - b0);
  }
  const [a, b] = tab[tab.length - 1];
  return x + b - a;
};
const COPY1V2 = shift(COPY1, viaTab(TAB1));
const COPY2V2 = shift(COPY2, viaTab(TAB2));
export const BQ1V2_FRAMES = Math.round(COPY1V2.dur * BQ_FPS);
export const BQ2V2_FRAMES = Math.round(COPY2V2.dur * BQ_FPS);

